def add(q,stem,cid,labels,solution,knowledge,opts,learning,cites,ambiguity='',calc=False,discipline='earth_interior'):
 r=by[q]
 out.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,summary=stem,conditions={'確認範囲':'問題幹、数値、単位、否定、全5候補を原典画像で照合した。','成立条件':knowledge},choices={str(i):dict(value=v,verdict=t,reason=s) for i,(v,t,s) in enumerate(opts,1)},figures='参照する図なし。プレート速度問題は5組の数値表を原典で確認。',ambiguity=ambiguity,evidence=[r['image']],core_concept=stem,required_knowledge=knowledge,solution=solution,answer_reason=solution,independent_answer=r['independent_answer'],independent_solution_note='公式正答の参照前に保存した初回解答を保持。'+r['reason'],learning_points=learning,theory_references=labels,discipline_id=discipline,concept_id=cid,cross_concepts=[],classification_reason='物質による地球の層区分、力学によるプレート、又は海洋の循環・物質収支を中心に分類する。内陸地震は地震学へ修正する。'+learning,calculation='true' if calc else 'false',figure='false',law='false',evaluation=dict(knowledge_novelty='2',reasoning_steps='2',calculation_load='1' if calc else '0',figure_reading='0',difficulty='2',difficulty_reason='物理専攻の静力学・回転系・波動を利用できるが、地学の典型値、層区分、海洋化学の用語を新たに対応させる。'),citations=cites,foundationality='high',transferability='high'))
def crust(q,quality=False):
 add(q,'地殻の位置・組成・厚さ・生成場所を、マントルとプレートの区分から判定する。','crust_moho_structure',['theory:interior:crust','theory:interior:moho','theory:interior:boundaries'],
 '海洋地殻は主として発散境界の海嶺でマグマが固まって形成される。海溝は海洋プレートが沈み込む側であり、海溝で形成されるとする4が不適切である。大陸と海洋の組成・厚さの典型的相違はこの形成と再循環の違いに対応する。',
 '地殻とプレートは別概念である。厚さには海水を含めない。花崗岩'+('質' if quality else '')+'層・玄武岩'+('質' if quality else '')+'層という二層像は平均的組成の近似として読む。',
 [('地殻は大きな層構造の最外層',T,'地殻・マントル・核という区分では最外側に位置する。大気をこの固体地球の区分に含めない。'),('大陸は花崗岩'+('質' if quality else '')+'層と玄武岩'+('質' if quality else '')+'層、海洋は玄武岩'+('質' if quality else '')+'層',C,'大陸上部は珪長質寄り、下部はより苦鉄質、海洋地殻は玄武岩・斑れい岩を主体とする。実岩石が全域で二つの均一層を作るという断定ではない。'),('大陸30〜40 km、海水を除く深海の地殻は大部分10 km未満',C,'代表的厚さの比較であり、山脈下の厚い地殻や海台などの例外を除く典型像である。'),('海洋地殻は海溝で形成',F,'新しい海洋地殻の主な生成場所は海嶺である。海溝の付加体形成と海洋地殻の生成を同一視しない。'),('地殻とマントルの境界はモホロビチッチ不連続面',T,'地震波の速度変化で認識される地殻底の境界である。リソスフェア底面とは異なる。')],
 '岩石組成の区分と力学的な硬さの区分を先に分け、生成する海嶺と沈み込む海溝を対にして覚える。',['usgs_interior_structure','usgs_plate_boundaries','umich_crust_teaching'],ambiguity='二つの均質な岩石層という記述と30〜40 kmの数値は近似である。原典の一般化を地球全域の厳密な組成・厚さの保証へ拡張しない。')
crust('H26-REG-APPLIED-30');crust('H28-REG-APPLIED-30',True);crust('H29-REG-APPLIED-26')
add('H27-REG-APPLIED-32','上載岩石の密度と厚さからモホ面の静岩圧を求める。','lithostatic_pressure',['theory:interior:pressure'],
 r'水平面の単位面積当たりに載る岩石の質量はρhである。上載荷重だけを考えるので \(p=\rho gh=(2.8\times10^3)(9.8)(35\times10^3)=9.604\times10^8\,\mathrm{Pa}=0.9604\,\mathrm{GPa}\)。最も近い1 GPaの4を選ぶ。',
 '厚さ35 km、平均密度2.8×10^3 kg/m³、重力加速度9.8 m/s²。上載荷重のみを考え、間隙流体の影響はないという原典指定を使用する。',
 [('1 MPa',F,'9.604×10^8 Paより約3桁小さい。'),('10 MPa',F,'導出圧力より約2桁小さい。'),('100 MPa',F,'導出圧力0.9604 GPaより約1桁小さい。'),('1 GPa',T,'9.604×10^8 Paを10^9 Paで割った0.9604 GPaに最も近い。'),('10 GPa',F,'導出圧力より約1桁大きい。')],
 'kmをmへ直し、密度×加速度×長さの単位がPaになることを確認する。静岩圧と間隙水圧及び有効応力を別にする。',['usgs_lithosphere2002'],calc=True)
add('H26-REG-APPLIED-32','内陸地殻内地震の発生位置・規模・深さと、同じ活断層の再来間隔を区別する。','intraplate_crustal_earthquake',['theory:interior:crust_quakes'],
 '地殻内地震は上盤側プレートの内部でも発生し、プレート境界地震と異なる。1995年兵庫県南部地震の気象庁マグニチュードは7.3であり、7を超えないという2には出題以前の反例がある。同じ活断層の活動間隔は通常人の寿命より長く、公式は5である。ただし「最も活発でも約1000年」を厳密な下限とするには断層群の定義と歴史資料の追加確認が必要である。',
 '内陸という語を震央が必ず陸上という意味に限定しない。気象庁マグニチュードとモーメントマグニチュードを混ぜない。再来間隔は全国の地震間隔でなく一つの断層である。',
 [('プレート境界で発生',F,'地殻内の活断層活動は上盤側のプレート内部でも起きる。境界面のすべりとの区別が必要である。'),('最大級でもM7を超えない',F,'出題前の兵庫県南部地震の気象庁M7.3が反例である。'),('震源はほとんど20 kmより深い',F,'上部地殻の脆性変形を主体とする浅い地震であり、厚い地殻のすべてが地震を起こすわけではない。'),('震央は陸上',F,'地殻内地震という発生機構の区分には沿岸の海域に震央を持つものも含み得る。地表の海陸区分だけで機構を決めない。'),('最も活発な活断層でも約1000年に1回',U,'公式が採る代表的な長期尺度である。同一断層の繰返しと各地の地震を区別する意図は妥当だが、全活断層の下限が1000年であるとの定量保証は未確定である。')],
 '発生機構・震源の深さ・震央の海陸・Mの尺度を分ける。平均間隔が長いことは近日の発生が不可能という意味ではない。',['jma_hyogo_history','herp_longterm_intervals'],ambiguity='正答5の「最も活発」「約1000年」は母集団と平均期間の定義が不足する。公式5と独立初回5は保持し、厳密な下限の主張は未解決とする。',discipline='earth_seismic')
add('R01-REG-APPLIED-30','固定した基準プレートに対する日本付近の二つの海洋プレートの速度の桁を比較する。','relative_plate_velocity',['theory:interior:velocity'],
 '日本付近の代表的沈み込み速度は太平洋プレートが年8〜9 cm、フィリピン海プレートが年4〜5 cmの桁である。候補では9 cm/年と4.5 cm/年の5が対応する。北アメリカ固定という原典の基準を保持し、一般的な日本列島に対する値と完全に同じモデルと証明したとは扱わない。',
 '原典は北アメリカプレート固定を明記する。剛体プレートの相対角速度と地点の位置から速度が決まるため、地点と運動モデルの省略を残す。',
 [('太平洋6.5 mm/年、フィリピン海2 mm/年',F,'両方が代表的cm/年の運動より一桁程度小さい。'),('太平洋8 mm/年、フィリピン海7 mm/年',F,'mm/年とcm/年の違いにより代表的な沈み込み速度に達しない。'),('太平洋2.5 cm/年、フィリピン海1.5 cm/年',F,'両方とも日本付近の代表的速度より小さい組である。'),('太平洋3 cm/年、フィリピン海8.5 cm/年',F,'太平洋の方が大きい代表比較が逆になっている。'),('太平洋9 cm/年、フィリピン海4.5 cm/年',C,'代表的な大きさと大小関係に対応する。原典にない地点・モデルを補って精密値としない。')],
 'cm/年は絶対値ではなく参照系と場所を伴う速度である。拡大速度、沈み込み速度、陸上GNSS点の速度を同じものとして比較しない。',['kagoshima_plate2019'],ambiguity='北アメリカ固定は明記されるが比較地点とオイラー極モデルは不明である。大学の解説は日本列島に対する代表速度であり、原典の参照系の厳密な数値検証は未完了である。')
def continental(q,new=False):
 opts=[('岩石の年代は約40億年前から現在',C,'大陸には約40億年前の古い岩石が残り、現在も岩石が形成される。地球の形成年代や最古ジルコンの年代そのものとは区別する。'),('平均厚さ30〜40 km',C,'代表的平均値であり、厚い山脈下や薄いリフトを含む全地点の範囲ではない。'),('下部は主に花崗岩質',F,'一般的な組成モデルで下部は上部より苦鉄質に富む。上部の珪長質組成を下部へ置き換えた記述である。'),('密度は上部より下部が大きい傾向',C,'下部の組成・圧力に対応する代表的傾向である。個々の局所岩体を密度だけで機械的に区分しない。'),('地殻表面積の約40%が大陸地殻',C,'大陸棚など海面下の大陸地殻を含む。陸地の面積比約3割とは分母対象が異なる。')]
 if new:opts=[opts[2],opts[0],opts[1],opts[3],opts[4]]
 add(q,'大陸地殻の上下の組成と密度、典型厚さ、年代、面積を整理する。','continental_crust_composition',['theory:interior:continental','theory:interior:ages'],
 '大陸地殻の上部は平均的に珪長質に富み、下部はそれより苦鉄質に富むというモデルである。下部が主に花崗岩質という'+('1' if new else '3')+'が不適切である。大陸地殻は陸地だけでなく海面下の大陸棚にも分布するため、面積約40%と陸地約30%を混同しない。',
 '地殻全体の表面積を分母とする。平均と全地点、現存岩石年代と地球誕生、岩石名と平均化学組成を区別する。',opts,
 '岩石名・上下・密度を関連付けて読み、40億年、40 km、40%という似た数字の次元と分母を分ける。',['umich_crust_teaching','tokyo_crust_gallery'],ambiguity='年代・厚さ・密度・面積は代表値と傾向である。二層の均一性や局所的な密度序列、約40%の厳密な境界定義まで原典は指定しない。')
continental('R02-REG-APPLIED-28');continental('R04-REG-APPLIED-26',True)
add('R01-RET-APPLIED-34','海洋底と大陸を、地殻厚さ・堆積・組成・年代の異なる尺度で比較する。','ocean_continent_contrast',['theory:interior:crust','theory:interior:ages'],
 '外洋の遠洋性海底では陸源物質の供給が少なく、堆積が遅いことが典型比較となり公式は2である。海洋地殻は薄く、海嶺生成と沈み込みにより現存海洋底の年代は通常数億年以内であり30億年ではない。花崗岩質岩石の全称否定には海洋斜長花崗岩や大陸棚などの範囲の問題があり、3の不適切性を無条件には確定しない。',
 '典型的な外洋底と大陸の比較であり、海底すべてを海洋地殻と同一視しない。モホの深さには海面又は固体表面という基準が必要である。',
 [('大洋底のモホは大陸より深い',F,'典型的海洋地殻は薄いため固体表面からのモホ深度は浅い。海面基準でも典型的大陸地殻より浅いが、基準と地域が未指定である。'),('大洋底の堆積速度は大陸より遅い',C,'陸源物質の供給が小さい遠洋域の典型である。大陸縁辺の高い堆積速度や大陸の無堆積・侵食域は例外である。'),('大洋底に花崗岩質岩石が存在',U,'典型的海洋地殻の主体が玄武岩・斑れい岩という説明だけでは、少量の珪長質岩や沈水した大陸地殻の存在を否定できない。原典の大洋底の範囲を要確認とする。'),('海洋地殻は大陸地殻より厚い',F,'典型的な厚さの大小が逆である。'),('大洋底の年代は0〜30億年',F,'プレートの再循環が続く現存外洋底は代表的に数億年以内であり、大陸の古い岩石の年代を当てはめている。')],
 '一般的な大小比較と存在命題を分ける。「主体でない」ことから「存在しない」を導かない。',['usgs_plate_boundaries','umich_crust_teaching'],ambiguity='大洋底の範囲・モホ深度の基準・堆積速度の地域比較が不明である。候補3の存在命題には例外の精査が必要であり、公式2だけを根拠に候補3を断定しない。')
add('R03-REG-APPLIED-31','三種のプレート境界とリフト・背弧の応力場を、生成・消費・横ずれで区別する。','plate_boundary_kinematics',['theory:interior:boundaries','theory:interior:ridge'],
 '海嶺区間の間にある活動的なトランスフォーム断層は両プレートの相対的な横ずれを担う。正断層は伸張で上盤が相対的に下がる断層であり、3の説明とは異なる。断裂帯全長が現在も活動するプレート境界という意味でもない。',
 '海嶺間の活動的なトランスフォーム区間と、その外側の非活動的な断裂帯を区別する。海嶺の高さと部分溶融は典型モデルとして扱う。',
 [('高温の新しい海洋プレートが低密度で海嶺は2〜3 km高い',C,'熱膨張と浮力による海嶺の隆起を説明する典型像である。特定の地形差の厳密値ではない。'),('遅い拡大では溶融度が小さくマグマをほとんど伴わない場合',C,'特に超低速拡大の一部ではマグマ供給が少なくマントル岩が露出し得る。遅い海嶺の全域が無マグマという意味ではない。'),('海嶺をつなぐ断裂帯で正断層運動しトランスフォームとなる',F,'活動区間での基本運動は横ずれである。周辺に局所的な正断層があることとは別の分類である。'),('大陸発散境界の正断層で伸張・薄化・地溝形成',T,'伸張する地殻の相対沈降とリフト形成を対応させた記述である。'),('沈み込み帯は圧縮だが背弧が伸張し拡大する場合',C,'沈み込みの存在は背弧の全域が常に圧縮であることを保証しない。海溝後退等に伴う背弧拡大がある。')],
 '境界の分類を断層名の連想で決めず、相対速度の方向を見て発散・収束・横ずれを判定する。',['usgs_plate_boundaries','umich_crust_teaching','noaa_ultraslow2004'],ambiguity='原典の海嶺高度と低速拡大時の溶融度は典型像であり、超低速域の地域条件は省略される。トランスフォームと非活動断裂帯は本文で区別する。')
add('R01-RET-APPLIED-33','島弧の海溝・火山帯・背弧海盆・熱流量・沈み込む地震面の配置を判定する。','island_arc_heat_flow',['theory:interior:arc','theory:interior:heat'],
 '東北日本弧の広域的な地殻熱流量は、太平洋側の前弧が低く、日本海側の火山・背弧側が高いという分布である。太平洋側で高く大陸側で低いとする4は、この方向を逆にしている。局所的な地下水の移流や火山近傍の異常を広域傾向と区別する。',
 '海溝側を前弧、反対の大陸側を背弧とする。日本の5島弧は通常の区分による。地殻熱流量は地表を通る熱流束であり、地下温度そのものではない。',
 [('5つの弧状列島から構成',C,'千島・東北日本・西南日本・伊豆小笠原・琉球という通常の区分で読む。島弧をさらに分割する流儀まで固定しない。'),('東北日本弧の太平洋側に6000 m以上の海溝が平行',T,'日本海溝と東北日本弧の沈み込み側の配置に対応する。'),('大陸側に縁海・背弧海盆',C,'日本海などの典型配置である。縁海という地理区分と背弧海盆という形成過程の区分は完全な同義ではない。'),('中部軸に火山帯、東北日本の熱流量は太平洋側で高く大陸側で低い',F,'火山帯の記述と合わせた複合肢のうち、熱流量の東西の大小が逆である。'),('海溝から大陸側へ深くなる深発地震面',T,'沈み込むスラブ内の地震分布が深部へ傾く和達・ベニオフ帯に対応する。')],
 '前弧・火山フロント・背弧を位置の関係で把握し、地温勾配、熱流束、地震面の深度を別の観測量として読む。',['gsj_heat_flow1991','usgs_plate_boundaries'],ambiguity='5島弧の区分と縁海の同義扱いは慣用的である。熱流量の広域傾向と地点ごとの地下水・火山の熱輸送を混同しない。')
add('R07-REG-APPLIED-24','地殻・マントルの組成境界とリソスフェア・アセノスフェアの力学境界を区別する。','lithosphere_asthenosphere',['theory:interior:lithosphere','theory:interior:moho'],
 'モホロビチッチ不連続面は地殻とマントルの境界である。リソスフェアには地殻だけでなく最上部マントルが含まれる。したがってリソスフェアとアセノスフェアの境界をモホとする4が不適切である。軟らかく流れるという性質は長い時間尺度の変形であり、マントル全体が液体という意味ではない。',
 '地球中心の温度は実験と内部モデルからの推定である。地殻・マントルという層と力学的硬さの層は境界位置が一致しない。主要プレート枚数は細分方法による。',
 [('温度は深部ほど高く中心約5000〜6000℃',C,'中心温度の代表的推定範囲である。全深度の厳密な単調性や直接測定値とはしない。'),('上部マントルに流れやすいアセノスフェア',T,'温度が高く長期的に変形しやすい領域であり、通常は主に固体である。'),('その上の硬いリソスフェア',T,'地殻と最上部マントルを含む、長期にも比較的強い層である。'),('両者の境界はモホ',F,'モホは地殻底であり、リソスフェア底の力学境界ではない。'),('10数〜20枚程度のプレートの実体はリソスフェア',C,'主要プレートという典型区分では妥当である。微小プレートを数えると枚数が増える。')],
 '物質の種類、地震波の速度、変形の時間尺度による区分を分ける。硬い層を地殻だけとみなさない。',['usgs_lithosphere2002','kagoshima_plate2019'],ambiguity='中心温度5000〜6000℃の推定根拠の精査は未完了である。主要プレート枚数と長期的硬さの区分の限定を保持する。')
def nutrient(q,new=False):
 salt=('外洋平均35‰、海水1 kg中に塩類約35 g',T,'原典は35‰でありOCRの35%ではない。質量比35/1000=0.035、約3.5%である。')
 age=('深層循環は最大2000年程度',U,'千年程度の循環尺度を表す概数として理解できるが、最大値には循環路と水塊年齢の定義が必要である。厳密な全球上限とは確定しない。')
 nodule=('遅い堆積速度の深海底にマンガン団塊',C,'ゆっくり成長する鉄・マンガン酸化物の団塊は、速い堆積で埋まらず海底面に保たれる環境と対応する。海山斜面のクラストとは別の形態である。')
 nutrients=('リン酸と溶存ケイ酸は表層で高く深部で低い',F,'表層では植物プランクトンに消費され、沈降物の分解等で深部へ再供給される。典型的な表層低・深層高の分布を逆にしている。')
 carbonate=('炭酸塩粒子は低温高圧の深海ほど速く溶解',U,'低温・高圧で溶けやすいという平衡傾向と、実際の溶解速度は別である。飽和度、粒子表面、海域による違いを無視した単調な速度増加は未確定である。')
 opts=[salt,age,nodule,nutrients,carbonate]
 if new:opts=[nutrients,age,salt,carbonate,nodule]
 add(q,'塩分の質量比と、海洋の生物作用・深層循環・堆積を組み合わせて鉛直分布を判定する。','ocean_nutrient_remineralization',['theory:ocean:salinity','theory:ocean:nutrients','theory:ocean:carbonate','theory:ocean:overturning'],
 '表層の光の届く層では植物プランクトンがリンやケイ素を取り込み、沈降した有機物や殻の分解・溶解で深部の水に戻る。したがって表層で高く深部で低いとする'+('1' if new else '4')+'が典型的な分布を逆転している。湧昇域などの例外や深部の濃度極大を考えると、逆向きも全深度の単調則ではない。',
 '塩分は原典画像の35‰を採用する。栄養塩の分布は典型的外洋での傾向であり、湧昇や高栄養塩海域を除外する全称ではない。',opts,
 '物質の鉛直輸送を生物による取込み・沈降・再生で考える。‰と%、循環時間と絶対的最大年齢、溶解度と速度を区別する。',['noaa_sea_salt','noaa_nutrient_observations','noaa_overturning','feely_carbonate2004','jamstec_deep_resources'],ambiguity='最大2000年の定義がなく、深海ほど速い溶解も平衡と速度を混在させる。公式'+('1' if new else '4')+'は保持するが、非正答肢の全称を無条件に真としない。',discipline='earth_ocean')
nutrient('H30-REG-APPLIED-19');nutrient('R04-REG-APPLIED-21',True)
def ocean(q,new=False):
 alk=('海水は弱アルカリ性で大気CO2を溶かす',T,'CO2の溶解と炭酸系の反応が進む。酸性化はpHの低下であり、直ちにpH7未満という意味ではない。')
 ooze=('石灰質軟泥は浅海にあり深海にほぼない',U,'深さだけでは判定できず、炭酸塩補償深度より浅い深海底にも石灰質堆積物が残る。補償深度より深い海底で残りにくいという限定が必要である。')
